func (c *Client) Login(email, password string, tenantSlug ...string) error {
	slug := ""
	if len(tenantSlug) > 0 {
		slug = tenantSlug[0]
	}
	auth, err := c.adapter.LoginTenant(context.Background(), email, password, slug)
	if err != nil {
		return err
	}
	c.BindAuth(auth)
	return nil
}

