func (s manualProfileStep) Run(ctx context.Context, rt *Runtime) error {
	profile, err := s.seeder.seedManualProfile(ctx, rt)
	if err != nil {
		return err
	}
	rt.AdditionalProfiles[profile.Key] = profile
	return nil
}

func (s printSummaryStep) Run(_ context.Context, rt *Runtime) error {
	if rt.Bootstrap == nil {
		return fmt.Errorf("bootstrap state not available")
	}
	if rt.Result == nil {
		return fmt.Errorf("seed result not available")
	}
	if s.seeder.options.StandingDemo {
		return nil
	}
	s.seeder.printSuccessSummary(rt.Bootstrap.AdminEmail, rt.Bootstrap.AdminPassword, rt.Result, rt.State)
	return nil
}

